const headers = $input.first().json.headers || {};
const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const token = String(lower['x-tradesejon-secret'] || lower['x-operator-token'] || lower['x-ceo-token'] || '');
const expected = String($env.WORKSHOP_LAUNCH_TOKEN || $env.TRADESAJON_BRIDGE_SECRET || '');
if (!expected || token !== expected) {
  return [{ json: { ok: false, authorized: false, httpStatus: 401, error: 'unauthorized' } }];
}
const body = $input.first().json.body || $input.first().json || {};
return [{ json: { ok: true, authorized: true, body } }];

const item = $input.first().json;
if (!item.authorized) return [{ json: item }];
const b = item.body || {};
if (!$env.MONGODB_URI) return [{ json: { ok: false, error: 'MONGODB_URI required for workshop seat reservation' } }];
const { MongoClient } = require('mongodb');
const client = new MongoClient($env.MONGODB_URI);
await client.connect();
const db = client.db($env.MONGODB_DB || 'tradesejon_prod');
const maxSeats = Number($env.WORKSHOP_MAX_SEATS || 20);
const count = await db.collection('workshop_seats').countDocuments({ status: 'confirmed' });
if (count >= maxSeats) {
  await client.close();
  return [{ json: { ok: false, seats_remaining: 0, error: `Workshop reached capacity (${maxSeats} seats)` } }];
}
await db.collection('workshop_seats').insertOne({
  full_name: String(b.full_name || 'Applicant'),
  email: String(b.email || '').toLowerCase(),
  phone: String(b.phone || ''),
  is_member: Boolean(b.is_member),
  status: 'confirmed',
  createdAt: new Date()
});
await client.close();
return [{ json: { ok: true, reserved: true, seats_remaining: maxSeats - count - 1 } }];
